import {
  BPMN_SPEC
} from "./packager-tool-jfv7t0c8.js";

// src/services/bpmn-action-type-validator.ts
class UnknownActionTypeError extends Error {
  code = "UnknownActionType";
  actionType;
  elementId;
  instructions;
  constructor(actionType, elementId, message, instructions) {
    super(message);
    this.name = "UnknownActionTypeError";
    this.actionType = actionType;
    this.elementId = elementId;
    this.instructions = instructions;
  }
}
function collectBpmnActionTypes(bpmnXml) {
  if (typeof bpmnXml !== "string" || bpmnXml.length === 0) {
    return [];
  }
  const elementIdRegex = /<bpmn:[A-Za-z]+\b[^>]*\bid="([^"]+)"/g;
  const actionTypeRegex = /<uipath:type\b[^>]*\bvalue="([^"]+)"/g;
  const elementIds = [];
  let elMatch = elementIdRegex.exec(bpmnXml);
  while (elMatch !== null) {
    elementIds.push({ index: elMatch.index, id: elMatch[1] });
    elMatch = elementIdRegex.exec(bpmnXml);
  }
  const references = [];
  let match = actionTypeRegex.exec(bpmnXml);
  while (match !== null) {
    const actionType = match[1];
    const matchIndex = match.index;
    let nearestId;
    for (const entry of elementIds) {
      if (entry.index <= matchIndex) {
        nearestId = entry.id;
      } else {
        break;
      }
    }
    references.push({ actionType, elementId: nearestId });
    match = actionTypeRegex.exec(bpmnXml);
  }
  return references;
}
function getKnownBpmnActionTypes() {
  return new Set(Object.keys(BPMN_SPEC.extensionTypes));
}
function validateBpmnActionTypes(bpmnXml) {
  const references = collectBpmnActionTypes(bpmnXml);
  if (references.length === 0) {
    return;
  }
  const known = getKnownBpmnActionTypes();
  const unknown = references.find((ref) => !known.has(ref.actionType));
  if (!unknown) {
    return;
  }
  const elementLabel = unknown.elementId ? ` on element ${unknown.elementId}` : "";
  throw new UnknownActionTypeError(unknown.actionType, unknown.elementId, `BPMN contains unknown action type '${unknown.actionType}'${elementLabel}.`, "Check the action type against `uip maestro flow registry search <type>` " + "or open the BPMN in Studio Web to repair.");
}

export { UnknownActionTypeError, collectBpmnActionTypes, getKnownBpmnActionTypes, validateBpmnActionTypes };

